import{_ as d,c as e,o as a,ae as o}from"./chunks/framework.Ck3L_38O.js";const b=JSON.parse('{"title":"astrbot_plugin_galgame_box","description":"","frontmatter":{},"headers":[],"relativePath":"Galgame百宝盒.md","filePath":"Galgame百宝盒.md"}'),r={name:"Galgame百宝盒.md"};function l(c,t,h,i,n,s){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="astrbot-plugin-galgame-box" tabindex="-1">astrbot_plugin_galgame_box <a class="header-anchor" href="#astrbot-plugin-galgame-box" aria-label="Permalink to &quot;astrbot_plugin_galgame_box&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p><a href="https://github.com/AstrBotDevs/AstrBot" target="_blank" rel="noreferrer">AstrBot</a>的社区插件，结合了VNDB和TouchGal的API，不但能够提供全面、细节的Galgame帮助信息，还能提供TouchGal的随机作品和资源下载等功能。后续会结合更多Gal网站的API提供更有趣的功能。</p><h2 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h2><p>本插件以 <strong><code>旮旯</code></strong> 作为主指令，后接空格与子指令即可调用各项功能。</p><h2 id="功能列表" tabindex="-1">功能列表 <a class="header-anchor" href="#功能列表" aria-label="Permalink to &quot;功能列表&quot;">​</a></h2><blockquote><p>演示使用 <strong><code>/</code></strong> 作为唤醒符</p></blockquote><h3 id="vndb-相关" tabindex="-1">VNDB 相关 <a class="header-anchor" href="#vndb-相关" aria-label="Permalink to &quot;VNDB 相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>指令格式</th><th>别名</th><th>说明</th></tr></thead><tbody><tr><td>指令查询</td><td><code>/旮旯</code></td><td><code>gal</code>、<code>GAL</code></td><td>指令组，查询子指令信息</td></tr><tr><td>作品查询</td><td><code>/旮旯 作品 &lt;作品名&gt;</code></td><td><code>游戏</code></td><td>搜索指定作品</td></tr><tr><td>角色查询</td><td><code>/旮旯 角色 &lt;角色名&gt;</code></td><td><code>人物</code></td><td>搜索指定角色</td></tr><tr><td>厂商查询</td><td><code>/旮旯 厂商 &lt;厂商名&gt;</code></td><td><code>作者</code></td><td>搜索指定厂商</td></tr><tr><td>ID 查询</td><td><code>/旮旯 ID &lt;VNDB ID&gt;</code></td><td><code>id</code></td><td>通过 VNDB ID 直接查询</td></tr></tbody></table><p><strong>关于ID查询参数 <code>&lt;VNDB ID&gt;</code>：</strong></p><ul><li>目前插件仅支持通过VNDB ID查询作品、角色和厂商</li></ul><h3 id="touchgal-相关" tabindex="-1">TouchGal 相关 <a class="header-anchor" href="#touchgal-相关" aria-label="Permalink to &quot;TouchGal 相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>指令格式</th><th>别名</th><th>说明</th></tr></thead><tbody><tr><td>随机作品</td><td><code>/旮旯 随机</code></td><td></td><td>随机获取一部作品</td></tr><tr><td>资源下载</td><td><code>/旮旯 下载 &lt;内容&gt;</code></td><td><code>资源</code></td><td>获取游戏资源</td></tr><tr><td>推荐作品</td><td><code>/旮旯 推荐 &lt;标签&gt;</code></td><td><code>标签</code></td><td>通过标签获取作品</td></tr></tbody></table><p><strong>关于资源下载参数 <code>&lt;内容&gt;</code>：</strong></p><ul><li>可以是 TouchGal 纯数字 ID</li><li>可以是 VNDB ID</li><li>其他情况下，将通过 TouchGal 搜索该内容并让用户选择结果</li></ul><p><strong>关于推荐作品参数 <code>&lt;标签&gt;</code>：</strong></p><ul><li>必填，否则请使用<strong>随机作品</strong>指令</li><li>标签可以是多个，多个标签请用<strong>空格</strong>分隔</li></ul><h3 id="animetrace-相关" tabindex="-1">AnimeTrace 相关 <a class="header-anchor" href="#animetrace-相关" aria-label="Permalink to &quot;AnimeTrace 相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>指令格式</th><th>别名</th><th>说明</th></tr></thead><tbody><tr><td>角色出处识别</td><td><code>/旮旯 出处 &lt;图片链接&gt;</code></td><td><code>识别</code></td><td>识别角色出处</td></tr></tbody></table><p><strong>使用说明：</strong></p><ul><li>如不填写参数，将开启会话等待用户发送图片</li><li><strong>图片链接</strong>只能在调用指令时参数传入，会话中不接受图片链接</li><li>支持引用一张图片进行识别</li></ul>',21)])])}const u=d(r,[["render",l]]);export{b as __pageData,u as default};
